import fs from 'node:fs';import path from 'node:path';import assert from 'node:assert/strict';import {pathToFileURL} from 'node:url';
const EVID=process.env.NAVKIT_E2E_EVID,runtime=process.env.NAVKIT_E2E_RUNTIME,pid=Number(process.env.NAVKIT_E2E_PID);
const {connect,shot,sleep,consoleLines}=await import(pathToFileURL(path.join(EVID,'harness.mjs')).href);const {page,browser}=await connect('http://127.0.0.1:9235');page.setDefaultTimeout(10000);await page.waitForFunction(()=>window.__TAURI_INTERNALS__&&window.__APP__);const assertions=[];const persist=()=>fs.writeFileSync(path.join(EVID,'report.json'),JSON.stringify({embeddedProduction:true,pid,url:page.url(),assertions,console:consoleLines},null,2));
const invoke=(cmd,args)=>page.evaluate(async({cmd,args})=>window.__TAURI_INTERNALS__.invoke(cmd,args),{cmd,args});
const node=id=>page.locator(`.tree-node[data-id="${id}"]`);const tool=label=>page.locator('.tab-tool-btn').getByText(label,{exact:true});
async function check(id,fn){try{const data=await fn();assertions.push({id,status:'PASS',data});console.log(`PASS ${id}`);}catch(e){assertions.push({id,status:'FAIL',error:String(e),stack:e.stack});console.log(`FAIL ${id} ${e}`);}try{await shot(page,id);}catch{}persist();}
const conn=`prod_${Date.now()}`,file=path.join(runtime,'production.sqlite'),name='Production-isolated';
await check('P01-EMBEDDED',async()=>{assert(!/localhost:5183|127\.0\.0\.1:5183/.test(page.url()));const assets=await page.evaluate(()=>({scripts:[...document.scripts].map(s=>s.src),styles:[...document.querySelectorAll('link[rel="stylesheet"]')].map(s=>s.href),css:getComputedStyle(document.querySelector('.titlebar')).display,mock:Boolean(window.__PREVIEW_MOCK__)}));assert(assets.scripts.some(s=>s.includes('/assets/')));assert(assets.styles.some(s=>s.includes('/assets/')));assert(!assets.scripts.some(s=>s.includes('/@vite')||s.includes('/src/')));assert(!assets.mock);assert.equal(assets.css,'flex');return {url:page.url(),assets};});
await check('P02-SQLITE',async()=>{await invoke('save_connection',{config:{id:conn,name,kind:'sqlite',host:'',port:0,user:'',password:'',database:'',file,params:'',group:'',read_only:false,keep_alive:false},password:''});await page.evaluate(async()=>{const a=window.__APP__;a.connections=await window.__TAURI_INTERNALS__.invoke('list_connections');a.refreshTree();});await node(`conn:${conn}`).dblclick();await page.waitForFunction(id=>window.__APP__.openConnections.has(id),conn);await invoke('execute_sql',{id:conn,sql:"CREATE TABLE items(id INTEGER PRIMARY KEY,grp INTEGER,name TEXT);INSERT INTO items VALUES(1,2,'alpha'),(2,1,'beta'),(3,1,'gamma'),(4,2,'delta');",database:null});await page.evaluate(async conn=>{const a=window.__APP__,n=a.tree.find(`conn:${conn}`);await a.loadChildren(n);n.expanded=true;a.tree.render();},conn);await node(`conn:${conn}/table/items`).dblclick();await page.waitForFunction(()=>window.__APP__.activeView()?.rowCount===4);assert.equal(await tool('导出').isEnabled(),true);return {file,rows:4};});
await check('P03-QUERY',async()=>{await node(`conn:${conn}/table/items`).click();await page.locator('.ribbon-btn').filter({has:page.locator('.ribbon-label').getByText('新建查询',{exact:true})}).click();await page.locator('.cm-content:visible').fill('SELECT COUNT(*) AS n FROM items;');await page.locator('.cm-content:visible').press('Control+Enter');await page.waitForFunction(()=>window.__APP__.activeTab?.results?.sets?.[0]?.rows?.[0]?.[0]==='4');return {count:4,schema:await page.evaluate(()=>window.__APP__.activeTab.schema)};});
await check('P04-FILTER',async()=>{await node(`conn:${conn}/table/items`).dblclick();await tool('筛选').click();const row=i=>page.locator('.filter-rows:visible .filter-row').nth(i);await row(0).locator('.fb-col').selectOption('id');await row(0).locator('.fb-val').fill('1');await page.getByRole('button',{name:'＋ 添加条件',exact:true}).click();await row(1).locator('.fb-col').selectOption('id');await row(1).locator('.fb-val').fill('2');await row(1).locator('.fb-join').selectOption('AND');await page.getByRole('button',{name:'应用筛选',exact:true}).click();await page.waitForFunction(()=>window.__APP__.activeView().rowCount===0);await row(1).locator('.fb-join').selectOption('OR');await page.getByRole('button',{name:'应用筛选',exact:true}).click();await page.waitForFunction(()=>window.__APP__.activeView().rowCount===2);await page.getByRole('button',{name:'清除筛选',exact:true}).click();await page.waitForFunction(()=>window.__APP__.activeView().rowCount===4);return {and:0,or:2,cleared:4};});
await check('P05-SORT',async()=>{await tool('排序').click();const add=page.getByRole('button',{name:'＋ 添加排序字段',exact:true});await add.click();await page.locator('.sort-row:visible').nth(0).locator('.fb-col').selectOption('grp');await add.click();await page.locator('.sort-row:visible').nth(1).locator('.fb-col').selectOption('id');await page.locator('.sort-row:visible').nth(1).locator('.fb-op').selectOption('desc');await page.getByRole('button',{name:'应用排序',exact:true}).click();await page.waitForFunction(()=>window.__APP__.activeView().grid.rows[0][0]==='3');const rows=await page.evaluate(()=>window.__APP__.activeView().grid.rows);assert.deepEqual(rows.map(r=>r[0]),['3','2','4','1']);return rows;});
await check('P06-BACKUP',async()=>{await node(`conn:${conn}`).click();await page.locator('.ribbon-btn').filter({has:page.locator('.ribbon-label').getByText('备份',{exact:true})}).click();await page.waitForFunction(()=>window.__APP__.activeTab?.kind==='backup');await tool('新建备份').click();const d=page.locator('.dialog').last();const buttons=await d.locator('button').allTextContents();const begin=d.getByRole('button',{name:/开始备份|开始|确定/}).last();await begin.click();await page.waitForFunction(()=>[...document.querySelectorAll('.toast')].some(e=>e.textContent.includes('备份完成')),null,{timeout:20000});const backups=await invoke('list_backups',{connectionId:conn,schemaName:'main'});assert(backups.length>0);const files=[];const walk=dir=>{for(const entry of fs.readdirSync(dir,{withFileTypes:true})){const p=path.join(dir,entry.name);if(entry.isDirectory())walk(p);else if(p.endsWith('.sql'))files.push(p);}};walk(path.join(runtime,'data'));assert(files.length>0);assert(files.some(p=>fs.readFileSync(p,'utf8').includes('items')));for(let i=0;i<files.length;i++)fs.copyFileSync(files[i],path.join(EVID,`backup-${i}.sql`));return {backups,files,buttons};});
await check('P07-WINDOW',async()=>{await page.locator('.titlebar-btn[aria-label="最小化"]').click();await page.waitForFunction(async()=>window.__TAURI_INTERNALS__.invoke('plugin:window|is_minimized',{label:'main'}));await invoke('plugin:window|unminimize',{label:'main'});await invoke('plugin:window|set_focus',{label:'main'});const before=await invoke('plugin:window|is_maximized',{label:'main'});await page.locator('.titlebar-btn[aria-label="最大化"]').click();await page.waitForFunction(async before=>(await window.__TAURI_INTERNALS__.invoke('plugin:window|is_maximized',{label:'main'}))!==before,before);await page.locator('.titlebar-btn[aria-label="最大化"]').click();return {pid,minimized:true,maximizeToggled:true};});
await check('P08-CLOSE-PID',async()=>{const settings=await invoke('get_settings');settings.confirm_on_close=true;await invoke('set_settings',{settings});await page.evaluate(settings=>window.__APP__.settings=settings,settings);await page.locator('.titlebar-btn.close').click();await page.locator('.dialog').getByRole('button',{name:'取消',exact:true}).click();process.kill(pid,0);await page.locator('.titlebar-btn.close').click();await page.locator('.dialog').getByRole('button',{name:'确定',exact:true}).click();let ended=false;for(let i=0;i<100;i++){try{process.kill(pid,0);}catch{ended=true;break;}await sleep(100);}assert(ended);return {pid,ended};});
await browser.close().catch(()=>{});process.exitCode=assertions.some(a=>a.status==='FAIL')?1:0;
